def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D array to store the number of chatting pairs that can be separated
    # by adding an aisle in each possible position
    num_separated = [[0 for _ in range(N)] for _ in range(M)]

    # Loop through each chatting pair and count the number of possible positions where
    # an aisle can be added to separate the chatting pair
    for (xi, yi, pi, qi) in chatting_pairs:
        for i in range(xi, pi):
            for j in range(yi, qi):
                num_separated[i][j] += 1
        for i in range(pi, xi):
            for j in range(yi, qi):
                num_separated[i][j] += 1
        for i in range(xi, pi):
            for j in range(qi, yi):
                num_separated[i][j] += 1
        for i in range(pi, xi):
            for j in range(qi, yi):
                num_separated[i][j] += 1

    # Loop through each possible position and determine the maximum number of chatting
    # pairs that can be separated by adding an aisle there
    max_separated = 0
    row_indices = []
    col_indices = []
    for i in range(M):
        for j in range(N):
