def hanoi_double_iterative(n: int) -> int:
    def hanoi_double_iterative_aux(n: int, moves: int) -> int:
        if n == 1:
            return moves + 1
        else:
            return hanoi_double_iterative_aux(n - 1, moves + 1) + hanoi_double_iterative_aux(n - 1, moves + 1)

    return hanoi_double_iterative_aux(n, 0)
```

```
def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        moves = 0
        while n > 1:
            moves += hanoi_double_iterative(n-1)
            n -= 1
        return moves
```

